import hashlib
import json


def process_data(records: list[dict]) -> dict:
    """Count valid records (dicts with an 'id' key) and compute a SHA-256 checksum over them."""
    valid = []
    for item in records:
        if isinstance(item, dict) and "id" in item:
            valid.append(item)

    hasher = hashlib.sha256()
    for item in valid:
        hasher.update(json.dumps(item, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8"))

    return {"processed": len(valid), "checksum": hasher.hexdigest()}

